  String get aboutSlogan => _t({AppLang.en: 'Travel online worldwide with a single QR code. 200+ countries, no SIM swap.', AppLang.zh: '\u5168\u7403\u65c5\u884c\u4e0a\u7f51\uff0c\u4e00\u4e2a\u4e8c\u7ef4\u7801\u641e\u5b9a\u3002\u8986\u76d6 200+ \u56fd\u5bb6\u548c\u5730\u533a\uff0c\u843d\u5730\u5373\u7528\uff0c\u65e0\u9700\u6362\u5361\u3002', AppLang.ja: 'QR\u30b3\u30fc\u30c9\u4e00\u3064\u3067\u4e16\u754c\u4e2d\u3067\u30aa\u30f3\u30e9\u30a4\u30f3\u3002200+\u30ab\u56fd\u30fb\u5730\u57df\u3002', AppLang.ko: 'QR \ucf54\ub4dc \ud558\ub098\ub85c \uc804 \uc138\uacc4 \uc778\ud130\ub137. 200\uac1c \uad6d\uac00.', AppLang.th: '\u0e2d\u0e2d\u0e19\u0e44\u0e25\u0e19\u0e4c\u0e17\u0e31\u0e48\u0e27\u0e42\u0e25\u0e01\u0e14\u0e49\u0e27\u0e22 QR \u0e40\u0e14\u0e35\u0e22\u0e27 200+ \u0e1b\u0e23\u0e30\u0e40\u0e17\u0e28', AppLang.vi: 'Du l\u1ecbch tr\u1ef1c tuy\u1ebfn to\u00e0n c\u1ea7u v\u1edbi m\u1ed9t m\u00e3 QR. 200+ qu\u1ed1c gia.'});

