  String get faq1Q => _t({AppLang.en: 'How do I activate the eSIM?', AppLang.zh: '\u5982\u4f55\u6fc0\u6d3b eSIM\uff1f', AppLang.ja: 'eSIM\u306e\u30a2\u30af\u30c6\u30a3\u30d9\u30fc\u30c8\u65b9\u6cd5\uff1f', AppLang.ko: 'eSIM\uc740 \uc5b4\ub5bb\uac8c \ud65c\uc131\ud654\ud558\ub098\uc694?', AppLang.th: '\u0e27\u0e34\u0e18\u0e35\u0e40\u0e1b\u0e34\u0e14\u0e43\u0e0a\u0e49 eSIM?', AppLang.vi: 'K\u00edch ho\u1ea1t eSIM th\u1ebf n\u00e0o?'});
  String get faq1A => _t({AppLang.en: 'After purchase go to Orders \u2192 View QR code, then scan it with your phone\u2019s Add eSIM.', AppLang.zh: '\u8d2d\u4e70\u540e\u8fdb\u5165\u300c\u8ba2\u5355\u300d\u2192\u300c\u67e5\u770b\u4e8c\u7ef4\u7801\u300d\uff0c\u7528\u624b\u673a\u8bbe\u7f6e\u91cc\u7684\u300c\u6dfb\u52a0 eSIM\u300d\u626b\u63cf\u5373\u53ef\u3002', AppLang.ja: '\u8cfc\u5165\u5f8c\u3001\u6ce8\u6587\u2192QR\u30b3\u30fc\u30c9\u3092\u8868\u793a\u3057\u3001\u8a2d\u5b9a\u306e\u300ceSIM\u3092\u8ffd\u52a0\u300d\u3067\u30b9\u30ad\u30e3\u30f3\u3057\u3066\u304f\u3060\u3055\u3044\u3002', AppLang.ko: '\uad6c\ub9e4 \ud6c4 \uc8fc\ubb38 \u2192 QR \ucf54\ub4dc \ubcf4\uae30\ub97c \ub204\ub974\uace0 \ud734\ub300\ud3f0 \uc124\uc815\uc5d0\uc11c eSIM \ucd94\uac00\ub85c \uc2a4\uce94\ud558\uc138\uc694.', AppLang.th: '\u0e2b\u0e25\u0e31\u0e07\u0e0b\u0e37\u0e49\u0e2d \u0e44\u0e1b\u0e04\u0e33\u0e2a\u0e31\u0e48\u0e07\u0e0b\u0e37\u0e49\u0e2d \u2192 \u0e14\u0e39 QR \u0e41\u0e25\u0e49\u0e27\u0e2a\u0e41\u0e01\u0e19\u0e14\u0e49\u0e27\u0e22\u0e40\u0e1e\u0e34\u0e48\u0e21 eSIM', AppLang.vi: 'Sau khi mua v\u00e0o \u0110\u01a1n h\u00e0ng \u2192 Xem QR, r\u1ed3i qu\u00e9t b\u1eb1ng Th\u00eam eSIM.'});
  String get faq2Q => _t({AppLang.en: 'Which phones are supported?', AppLang.zh: '\u652f\u6301\u54ea\u4e9b\u624b\u673a\uff1f', AppLang.ja: '\u5bfe\u5fdc\u7aef\u672b\u306f\uff1f', AppLang.ko: '\uc5b4\ub290 \ud734\ub300\ud3f0\uc774 \uc9c0\uc6d0\ub418\ub098\uc694?', AppLang.th: '\u0e23\u0e2d\u0e07\u0e23\u0e31\u0e1a\u0e21\u0e37\u0e2d\u0e16\u0e37\u0e2d\u0e2d\u0e30\u0e44\u0e23\u0e1a\u0e49\u0e32\u0e07?', AppLang.vi: 'Nh\u1eefng \u0111i\u1ec7n tho\u1ea1i n\u00e0o h\u1ed7 tr\u1ee3?'});
  String get faq2A => _t({AppLang.en: 'iPhone XS and later, and most recent Android flagships. Search for eSIM in your phone settings to confirm.', AppLang.zh: 'iPhone XS \u53ca\u4ee5\u4e0a\u3001\u5927\u90e8\u5206\u8fd1\u5e74\u5b89\u5353\u65d7\u8230\u5747\u652f\u6301 eSIM\u3002\u53ef\u5728\u624b\u673a\u8bbe\u7f6e\u4e2d\u641c\u7d22\u300ceSIM\u300d\u786e\u8ba4\u3002', AppLang.ja: 'iPhone XS\u4ee5\u964d\u3068\u6700\u8fd1\u306eAndroid\u30d5\u30e9\u30c3\u30b0\u30b7\u30c3\u30d7\u3002', AppLang.ko: 'iPhone XS \uc774\uc0c1 \ubc0f \ucd5c\uadfc \uc548\ub4dc\ub85c\uc774\ub4dc \ud50c\ub798\uadf8\uc2ed\uc785\ub2c8\ub2e4.', AppLang.th: 'iPhone XS \u0e02\u0e36\u0e49\u0e19\u0e44\u0e1b \u0e41\u0e25\u0e30 Android \u0e23\u0e38\u0e48\u0e19\u0e43\u0e2b\u0e21\u0e48', AppLang.vi: 'iPhone XS tr\u1edf l\u00ean v\u00e0 h\u1ea7u h\u1ebft Android cao c\u1ea5p.'});
