  String get faq3A => _t({AppLang.en: 'Buy another plan from My Plans or contact support.', AppLang.zh: '\u53ef\u5728\u300c\u6211\u7684\u5957\u9910\u300d\u91cc\u300c\u518d\u6b21\u8d2d\u4e70\u300d\u7eed\u8ba2\uff0c\u6216\u8054\u7cfb\u5ba2\u670d\u3002', AppLang.ja: '\u300c\u30de\u30a4\u30d7\u30e9\u30f3\u300d\u3067\u8ffd\u52a0\u8cfc\u5165\u3059\u308b\u304b\u3001\u30b5\u30dd\u30fc\u30c8\u306b\u3054\u9023\u7d61\u304f\u3060\u3055\u3044\u3002', AppLang.ko: '\ub0b4 \ud50c\ub79c\uc5d0\uc11c \ucd94\uac00 \uad6c\ub9e4\ud558\uac70\ub098 \uace0\uac1d\uc13c\ud130\uc5d0 \ubb38\uc758\ud558\uc138\uc694.', AppLang.th: '\u0e0b\u0e37\u0e49\u0e2d\u0e40\u0e1e\u0e34\u0e48\u0e21\u0e43\u0e19\u0e41\u0e1e\u0e25\u0e31\u0e19\u0e02\u0e2d\u0e07\u0e09\u0e31\u0e19', AppLang.vi: 'Mua th\u00eam g\u00f3i \u1edf G\u00f3i c\u1ee7a t\u00f4i ho\u1eb7c li\u00ean h\u1ec7 h\u1ed7 tr\u1ee3.'});
  String get faq4Q => _t({AppLang.en: 'Can I get a refund?', AppLang.zh: '\u80fd\u9000\u6b3e\u5417\uff1f', AppLang.ja: '\u8fd4\u91d1\u3067\u304d\u307e\u3059\u304b\uff1f', AppLang.ko: '\ud658\ubd88\ub418\ub098\uc694?', AppLang.th: '\u0e02\u0e2d\u0e04\u0e37\u0e19\u0e40\u0e07\u0e34\u0e19\u0e44\u0e14\u0e49\u0e2b\u0e23\u0e37\u0e2d\u0e44\u0e21\u0e48?', AppLang.vi: 'C\u00f3 \u0111\u01b0\u1ee3c ho\u00e0n ti\u1ec1n kh\u00f4ng?'});
  String get faq4A => _t({AppLang.en: 'Unactivated eSIMs can be refunded within 7 days. Activated ones cannot.', AppLang.zh: '\u672a\u6fc0\u6d3b\u7684 eSIM \u652f\u6301 7 \u5929\u5185\u9000\u6b3e\uff0c\u6fc0\u6d3b\u540e\u4e0d\u652f\u6301\u3002', AppLang.ja: '\u672a\u30a2\u30af\u30c6\u30a3\u30d9\u30fc\u30c8\u306e eSIM \u306f7\u65e5\u4ee5\u5185\u8fd4\u91d1\u53ef\u80fd\u3002', AppLang.ko: '\ubbf8\ud65c\uc131\ud654 eSIM\uc740 7\uc77c \ub0b4 \ud658\ubd88 \uac00\ub2a5\ud569\ub2c8\ub2e4.', AppLang.th: 'eSIM \u0e17\u0e35\u0e48\u0e22\u0e31\u0e07\u0e44\u0e21\u0e48\u0e40\u0e1b\u0e34\u0e14\u0e43\u0e0a\u0e49\u0e04\u0e37\u0e19\u0e44\u0e14\u0e49\u0e20\u0e32\u0e22\u0e43\u0e19 7 \u0e27\u0e31\u0e19', AppLang.vi: 'eSIM ch\u01b0a k\u00edch ho\u1ea1t ho\u00e0n ti\u1ec1n trong 7 ng\u00e0y.'});
  String get faq5Q => _t({AppLang.en: 'No internet on arrival?', AppLang.zh: '\u843d\u5730\u6ca1\u7f51\u600e\u4e48\u529e\uff1f', AppLang.ja: '\u73fe\u5730\u3067\u7e4b\u304c\u3089\u306a\u3044\u5834\u5408\u306f\uff1f', AppLang.ko: '\ub3c4\ucc29 \ud6c4 \uc778\ud130\ub137\uc774 \uc548 \ub418\uba74?', AppLang.th: '\u0e44\u0e21\u0e48\u0e21\u0e35\u0e40\u0e19\u0e47\u0e15\u0e15\u0e2d\u0e19\u0e16\u0e36\u0e07?', AppLang.vi: 'Kh\u00f4ng c\u00f3 m\u1ea1ng khi \u0111\u1ebfn?'});
  String get faq5A => _t({AppLang.en: 'Make sure data roaming is on and set this eSIM as the mobile data line.', AppLang.zh: '\u786e\u8ba4\u5df2\u5f00\u542f\u6570\u636e\u6f2b\u6e38\uff0c\u5e76\u5728\u624b\u673a\u8bbe\u7f6e\u4e2d\u628a\u672c eSIM \u8bbe\u4e3a\u79fb\u52a8\u6570\u636e\u4e3b\u5361\u3002', AppLang.ja: '\u30c7\u30fc\u30bf\u30ed\u30fc\u30df\u30f3\u30b0\u3092ON\u306b\u3057\u3001\u3053\u306e eSIM \u3092\u30e2\u30d0\u30a4\u30eb\u30c7\u30fc\u30bf\u7528\u306b\u8a2d\u5b9a\u3057\u3066\u304f\u3060\u3055\u3044\u3002', AppLang.ko: '\ub370\uc774\ud130 \ub85c\ubc0d\uc744 \ucf1c\uace0 \uc774 eSIM\uc744 \ubaa8\ubc14\uc77c \ub370\uc774\ud130\ub85c \uc124\uc815\ud558\uc138\uc694.', AppLang.th: '\u0e40\u0e1b\u0e34\u0e14\u0e42\u0e23\u0e21\u0e34\u0e48\u0e07\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25 \u0e41\u0e25\u0e30\u0e15\u0e31\u0e49\u0e07 eSIM \u0e40\u0e1b\u0e47\u0e19\u0e0b\u0e34\u0e21\u0e02\u0e49\u0e2d\u0e21\u0e39\u0e25', AppLang.vi: 'B\u1eadt chuy\u1ec3n v\u00f9ng d\u1eef li\u1ec7u v\u00e0 \u0111\u1eb7t eSIM n\u00e0y l\u00e0m d\u1eef li\u1ec7u di \u0111\u1ed9ng.'});

